package io.aetherdb.codec;
import io.aetherdb.api.typed.*;import java.nio.*;
public final class TypedKeyEnvelope{public static final int PREFIX_BYTES=19;private TypedKeyEnvelope(){}public static <K>byte[]encode(CollectionDefinition<K,?>d,K key){byte[]user=d.keyCodec().encode(key);if(user==null||user.length>d.keyCodec().maximumEncodedSize())throw new IllegalArgumentException("encoded key exceeds codec bound");ByteBuffer b=ByteBuffer.allocate(PREFIX_BYTES+user.length).order(ByteOrder.BIG_ENDIAN);b.put(prefix(d)).put(user);return b.array();}public static <K>K decode(CollectionDefinition<K,?>d,byte[]physical){byte[]p=prefix(d);if(physical.length<p.length||!java.util.Arrays.equals(p,java.util.Arrays.copyOf(physical,p.length)))throw new IllegalArgumentException("key is outside collection");return d.keyCodec().decode(java.util.Arrays.copyOfRange(physical,p.length,physical.length));}public static byte[]prefix(CollectionDefinition<?,?>d){ByteBuffer b=ByteBuffer.allocate(PREFIX_BYTES).order(ByteOrder.BIG_ENDIAN);b.put((byte)0x40).putLong(d.id().value().getMostSignificantBits()).putLong(d.id().value().getLeastSignificantBits()).putShort((short)d.keyCodec().encodingVersion());return b.array();}public static byte[]prefixEnd(CollectionDefinition<?,?>d){byte[]end=prefix(d);for(int i=end.length-1;i>=0;i--)if((end[i]&255)!=255){end[i]++;return java.util.Arrays.copyOf(end,i+1);}throw new IllegalArgumentException("collection prefix has no successor");}}
